'use strict';
(()=>{const data={"source":{"id":"cvp-working-2026","title":"CVP 112 + MOL 114 Working Document · CVP A1–A13 / P1–P15","url":"/working-document-source.html","pages":67,"kind":"topic","linkLabel":"Source text & figures"},"questions":[{"id":"cvp-working-A1-1","source":"cvp-working-2026","page":3,"endPage":3,"number":"A1-1","question":"An infant is born with an abnormally thin wall in the smooth part of the right atrium. This condition may be related to the underdevelopment of which of the following embryonic structures?","options":["Pulmonary trunk","Conus Cordis","Sinus Venosus","Truncus Arteriosus","Ascending Aorta"],"letters":["A","B","C","D","E"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A1","figures":[],"sourceExplanation":"The right horn of the sinus venosus will give rise to the smooth lining of the right atrium. A and E are incorrect as they are derivatives of the embryonic structure rather than a source. B is incorrect as it is a derivative of Bubus Cordis. D is incorrect as it forms proximal parts of the pulmonary trunk and aorta."},{"id":"cvp-working-A1-2","source":"cvp-working-2026","page":3,"endPage":3,"number":"A1-2","question":"What is the clinical importance of the space between the outﬂow and inﬂow regions of the initial development of the heart?","options":["The space is known for the presence of autonomic nerves","Absence of the space leads to dextrocardia","The covering pericardium needs reﬂection to expose great vessels","Clamping of big vessels is possible in surgery","Echocardiography reveals oblique sinus at this region"],"letters":["A","B","C","D","E"],"printedAnswer":"D","answer":3,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A1","figures":[],"sourceExplanation":"The space between the outﬂow regions (truncus arteriosus) and inﬂow regions (Sinus venosus) will eventually form the transverse Sinus. During coronary artery bypass grafting, the pulmonary artery and aorta are clamped and the blood is diverted to a coronary bypass machine."},{"id":"cvp-working-A1-3","source":"cvp-working-2026","page":4,"endPage":4,"number":"A1-3","question":"The sinoatrial node will develop primarily from which embryonic structure?","options":["Right Atrium","Umbilical Vein","Sinus Venosus","Vitelline Vein"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A1","figures":[],"sourceExplanation":"The sinus venosus will eventually form the coronary sinus, sinoatrial node and the posterior (smooth) part of the right atrium."},{"id":"cvp-working-A2-1","source":"cvp-working-2026","page":4,"endPage":4,"number":"A2-1","question":"A patient has a small but solid tumor in the mediastinum, which is conﬁned at the level of the sternal angle. Which of the following structures would most likely be found at this level?","options":["Bifurcation of the trachea","Beginning of the ascending aorta","Middle of the aortic arch","Articulation of the third rib with the sternum","Superior border of the superior mediastinum"],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A2","figures":[],"sourceExplanation":"The sternal angle is the junction of the manubrium and the body of the sternum. It is located at the level where the second rib articulates with the sternum, the trachea bifurcates into the right and left bronchi, and the aortic arch begins and ends. It marks the end of the ascending aorta and the beginning of the descending aorta, and it forms the inferior border of the superior mediastinum."},{"id":"cvp-working-A2-2","source":"cvp-working-2026","page":5,"endPage":5,"number":"A2-2","question":"A person diagnosed with a cervical rib presents with numbness, tingling, and pain down his arms; compression of which of the following nervous structures is most directly responsible for these symptoms?","options":["T1 spinal nerve","Phrenic nerve","Intercostal nerve","Vagus nerve","Brachiocephalic vein"],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A2","figures":[],"sourceExplanation":"A cervical rib can compress the lower trunk of the brachial plexus (C8–T1), causing thoracic outlet syndrome. This results in pain, numbness, and tingling radiating down the arm, particularly along the medial forearm and hand."},{"id":"cvp-working-A2-3","source":"cvp-working-2026","page":5,"endPage":6,"number":"A2-3","question":"A 32-year-old man is brought to the emergency department following a motor vehicle accident. He complains of severe right-sided chest pain that worsens during inspiration and coughing. A chest radiograph reveals a fracture of the right seventh rib, located just anterior to its angle. Further imaging suggests the fracture extends toward the rib's posterior articulation. The physician reviews the rib's normal anatomical attachments to assess potentially affected structures. Which of the following correctly describes the normal posterior articulations of the fractured rib?","options":["Its head articulates with the bodies of T7 and T8, while its tubercle articulates with the transverse process of T7.","Its head articulates exclusively with the body of T7, while its tubercle articulates with the transverse process of T6.","Its head articulates with the bodies of T6 and T7 and the intervening intervertebral disc, while its tubercle articulates with the transverse process of T7.","Its head articulates with the bodies of T6 and T7, while its tubercle articulates with the transverse process of T6.","Its head articulates exclusively with the body of T7, while its tubercle articulates with the transverse process of T7."],"letters":["A","B","C","D","E"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A2","figures":[],"sourceExplanation":"The seventh rib is a typical rib whose head articulates with the bodies of T6 and T7 and their intervening intervertebral disc, while its tubercle articulates with the transverse process of T7. Generally, the head of a typical rib articulates with its corresponding vertebra and the vertebra immediately above, whereas its tubercle articulates only with the corresponding vertebra."},{"id":"cvp-working-A3-1","source":"cvp-working-2026","page":6,"endPage":6,"number":"A3-1","question":"A healthy 22-year-old man undergoes an ECG during a routine examination. His QRS complexes show normal ventricular depolarization. Which sequence best represents the direction of electrical activation across his ventricular wall?","options":["Myocardium → Endocardium → Epicardium","Epicardium → Myocardium → Endocardium","Endocardium → Myocardium → Epicardium","Myocardium → Epicardium → Endocardium"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A3","figures":[],"sourceExplanation":"The impulse spreads from deep to superﬁcial layers. Purkinje ﬁbers in the subendocardium deliver the impulse to the ventricular myocardium. The impulse then spreads outwards toward the epicardium triggering ventricular contraction."},{"id":"cvp-working-A3-2","source":"cvp-working-2026","page":6,"endPage":7,"number":"A3-2","question":"Which option identiﬁes all junction types that together provide mechanical attachment and electrical communication between adjacent cardiac muscle cells at intercalated discs?","options":["Desmosomes + Zonula adherens","Desmosomes + Gap junctions + Fascia adherens","Desmosomes + Gap junctions","Hemidesmosomes + Fascia adherens","Tight junctions + Desmosomes + Fascia adherens"],"letters":["A","B","C","D","E"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A3","figures":[],"sourceExplanation":"Desmosomes and fascia adherens hold heart muscle cells together (mechanical attachment) . Gap junctions let electrical impulses pass between them (electrical communication) . The other choices either leave one out or include a junction that does not belong in intercalated discs."},{"id":"cvp-working-A3-3","source":"cvp-working-2026","page":7,"endPage":7,"number":"A3-3","question":"Which statement correctly describes cardiac muscle?","options":["Its T-tubules occur at Z discs.","Its T-tubules are narrower than those in skeletal muscle.","Its contractile apparatus lacks troponin.","Its T-tubules form triads with the sarcoplasmic reticulum.","Its contraction is triggered by oxytocin."],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A3","figures":[],"sourceExplanation":"Cardiac muscle T-tubules are wider than skeletal muscle T-tubules and are lined by an external lamina resembling a basal lamina. They lie at Z discs, where they commonly form dyads rather than triads."},{"id":"cvp-working-A4-1","source":"cvp-working-2026","page":7,"endPage":7,"number":"A4-1","question":"During a cardiac surgery, a surgeon passes clamp posterior to the ascending aorta and the pulmonary trunk, but anterior to the superior vena cava. Through which space is the clamp being passed?","options":["Anterior mediastinum","Atrioventricular groove","Transverse sinus","Coronary sulcus"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A4","figures":[],"sourceExplanation":"The posterior interventricular artery ( PIA ) runs in the posterior interventricular sulcus, and the middle cardiac vein travels alongside it in the same groove","sourceIssue":"The source explanation appears to belong to another question in this section. The supplied letter key is retained."},{"id":"cvp-working-A4-2","source":"cvp-working-2026","page":8,"endPage":8,"number":"A4-2","question":"A 52-year-old patient is admitted to the hospital with severe chest pain. ECG and radiographic examinations provide evidence of a signiﬁcant myocardial infarction and cardiac tamponade. An emergency pericardiocentesis is ordered. At which of the following locations will the needle best be inserted to relieve the tamponade","options":["Right seventh intercostal space in the midaxillary line","Left ﬁfth intercostal space in the midclavicular line","Right third intercostal space, 1 inch lateral to the sternum","Left sixth intercostal space, 1 ⁄2 inch lateral to the sternum"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A4","figures":[],"sourceExplanation":"During pericardiocentesis, the needle is inserted below the xiphoid process or in the left ﬁfth intercostal space at the midclavicular line. The most effective way to drain the pericardium is to penetrate the thoracic wall at its lowest anatomical point."},{"id":"cvp-working-A4-3","source":"cvp-working-2026","page":8,"endPage":9,"number":"A4-3","question":"A 48-year-old male patient is scheduled to have a coronary arterial bypass because of chronic angina. Coronary arteriography reveals nearly total blockage of the posterior descending interventricular artery. In exposing this artery to perform the bypass procedure, which accompanying vessel is most susceptible to injury?","options":["Middle cardiac vein","Small cardiac vein","Great cardiac vein","Coronary sinus"],"letters":["A","B","C","D"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A4","figures":[],"sourceExplanation":"The transverse sinus is a passage within the pericardial sac located posterior to the ascending aorta and pulmonary trunk and anterior to the superior vena cava.","sourceIssue":"The source explanation appears to belong to another question in this section. The supplied letter key is retained."},{"id":"cvp-working-A5-1","source":"cvp-working-2026","page":9,"endPage":9,"number":"A5-1","question":"A 3-year-old male patient presents with a clinically signiﬁcant atrial septal defect (ASD). The ASD usually results from incomplete closure of which of the following structures?","options":["Foramen ovale","Ligamentum arteriosum","Ductus arteriosus","Sinus venarum","Coronary sinus"],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A5","figures":[],"sourceExplanation":"An ASD commonly results from incomplete closure of the foramen ovale, which normally closes after birth when left atrial pressure rises above right atrial pressure."},{"id":"cvp-working-A5-2","source":"cvp-working-2026","page":9,"endPage":10,"number":"A5-2","question":"A 50-year-old man presents with shortness of breath and dizziness during exercise. On examination, the physician detects a murmur caused by an abnormal aortic valve. At which location should the stethoscope be placed to best hear this murmur?","options":["Left 2nd intercostal space","Right 2nd intercostal space","Left 4th intercostal space","Left 5th intercostal space","Sub-xiphoid point"],"letters":["A","B","C","D","E"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A5","figures":[],"sourceExplanation":"This is the aortic auscultation area, because it is where the blood ﬂow hits the chest wall"},{"id":"cvp-working-A5-3","source":"cvp-working-2026","page":10,"endPage":10,"number":"A5-3","question":"Which structure in the right ventricle carries a major part of the right bundle branch of the cardiac conduction system?","options":["Crista terminalis","Moderator band","Pectinate muscles","Trabeculae carneae","Papillary muscles"],"letters":["A","B","C","D","E"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A5","figures":[],"sourceExplanation":"It carries a major part of the right bundle branch from the interventricular septum toward the anterior papillary muscle."},{"id":"cvp-working-A6-1","source":"cvp-working-2026","page":10,"endPage":10,"number":"A6-1","question":"Which vessel supplies the Right and Left Bundle Branches?","options":["Posterior Interventricular Artery","Anterior Interventricular Artery","Circumﬂex Artery","Right Coronary Artery"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A6","figures":[],"sourceExplanation":"The LAD supplies the anterior two-thirds of the interventricular septum, where the right and left bundle branches travel."},{"id":"cvp-working-A6-2","source":"cvp-working-2026","page":11,"endPage":11,"number":"A6-2","question":"Coronary artery disease is a frequent cause of myocardial infarction in the United States. If an echocardiogram suggests reduced posterior ventricular wall movement, there will be reduced blood ﬂow within which of the following coronary arteries and veins?","options":["Circumﬂex branch of the left artery; great cardiac vein","Anterior interventricular artery; great cardiac vein","Anterior interventricular artery; middle cardiac vein","Right marginal branch of the right artery; small cardiac vein","Posterior interventricular artery; middle cardiac vein"],"letters":["A","B","C","D","E"],"printedAnswer":"E","answer":4,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A6","figures":[],"sourceExplanation":". The posterior interventricular artery (PDA) supplies the posterior/inferior region of the ventricles, while the middle cardiac vein drains blood from this region. Both vessels run together in the posterior interventricular sulcus, so reduced blood supply to this area can cause decreased posterior ventricular wall movement."},{"id":"cvp-working-A6-3","source":"cvp-working-2026","page":11,"endPage":11,"number":"A6-3","question":"A 68-year-old man presents with an acute myocardial infarction. Coronary angiography reveals an occlusion of the proximal left circumﬂex artery. Further examination conﬁrms that the patient has a left-dominant coronary circulation.Which of the following combinations of structures is most likely to experience ischemia?","options":["Anterior two-thirds of the interventricular septum, apex of the heart, and right bundle branch","Inferior wall of the left ventricle, posterior one-third of the interventricular septum, and AV node","Right ventricular free wall, SA node, and anterior papillary muscle of the right ventricle","Anterior wall of the left ventricle, anterior papillary muscle of the left ventricle, and left bundle branch","Right atrium, right ventricular free wall, and posterior one-third of the interventricular sept"],"letters":["A","B","C","D","E"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A6","figures":[],"sourceExplanation":"In left-dominant coronary circulation, the posterior interventricular artery (PDA) arises from the left circumﬂex artery (LCx) rather than the RCA. Therefore, a proximal LCx occlusion can cause ischemia of the inferior wall of the left ventricle, posterior one-third of the interventricular septum, and AV node, since these regions receive blood from branches of the dominant LCx."},{"id":"cvp-working-A7-1","source":"cvp-working-2026","page":12,"endPage":12,"number":"A7-1","question":"Which layer of a blood vessel is responsible for vasoconstriction and vasodilation","options":["Tunica intima","Tunica media","Tunica externa","Endothelium"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A7","figures":[],"sourceExplanation":"The tunica media contains smooth muscle cells. These contract or relax to control the diameter of the vessel, regulating blood ﬂow and pressure. Lecture: Blood Vessel Histology Dr. Ani"},{"id":"cvp-working-A7-2","source":"cvp-working-2026","page":12,"endPage":13,"number":"A7-2","question":"Which speciﬁc histological feature and structural composition primarily distinguishes a large elastic artery (such as the aorta) from a medium muscular artery?","options":["Presence of an internal elastic lamina instead of fenestrated elastic lamellae","Presence of 30 to 40 circular smooth muscle sheets and 40 to 70 fenestrated elastic lamellae in the tunica media","Absence of any smooth muscle cell within the tunica media","Presence of prominent valves within the lumen to prevent backﬂow"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A7","figures":[],"sourceExplanation":"Large elastic arteries (conducting arteries like the aorta) are uniquely characterized in their tunica media by a high ratio of fenestrated elastic lamellae (40 to 70 layers) compared to circular smooth muscle sheets (30 to 40 layers) to handle high pressure and allow expansion and recoil during systole. In contrast, medium muscular arteries have fewer elastic layers, with distinct internal and external elastic laminae bounding a thicker smooth muscle layer."},{"id":"cvp-working-A7-3","source":"cvp-working-2026","page":13,"endPage":13,"number":"A7-3","question":"Vasa vasorum function in a way that is similar to","options":["AV valves","Semilunar valves","Coronary arteries","Elastic arteries"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A7","figures":[],"sourceExplanation":""},{"id":"cvp-working-A8-1","source":"cvp-working-2026","page":13,"endPage":14,"number":"A8-1","question":"A 31-year-old male is suffering from a penetrating wound to the 8th intercostal space along the paravertebral line. The artery which supplies the intercostal space is bleeding. Which of the following vessels is this artery a branch of?","options":["Thoracic descending aorta","Pulmonary artery","Common carotid","Internal thoracic artery","Left subclavian artery"],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A8","figures":[],"sourceExplanation":"The 8th posterior intercostal artery arises directly from the descending thoracic aorta, which supplies the 3rd–11th posterior intercostal spaces. Since the injury is located along the paravertebral line of the 8th intercostal space, the bleeding vessel is a branch of the descending thoracic aorta."},{"id":"cvp-working-A8-2","source":"cvp-working-2026","page":14,"endPage":14,"number":"A8-2","question":"A 52-year-old woman undergoes surgery for removal of a mediastinal mass. During the procedure, the surgeon accidentally injures a major lymphatic vessel ascending through the posterior mediastinum. Postoperative imaging conﬁrms damage to the vessel responsible for draining lymph from both lower limbs, the abdominal cavity, and the left upper limb.Which of the following structures is the MOST likely site where this injured vessel normally empties into the venous circulation ?","options":["Junction of the right internal jugular and right subclavian veins","Junction of the left internal jugular and left subclavian veins","Junction of the right and left brachiocephalic veins","Junction of the superior vena cava and right atrium","Junction of the azygos vein and superior vena cava"],"letters":["A","B","C","D","E"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A8","figures":[],"sourceExplanation":"The thoracic duct drains lymph from both lower limbs, the abdominal cavity, and the left upper limb, as well as other regions comprising approximately three-quarters of the body. It ascends through the posterior mediastinum and empties into the left venous angle, formed by the junction of the left internal jugular and left subclavian veins."},{"id":"cvp-working-A8-3","source":"cvp-working-2026","page":15,"endPage":15,"number":"A8-3","question":"In coronary bypass graft surgery of a 49-year-old female, the internal thoracic artery is used as the coro- nary artery bypass graft. The anterior intercostal arter- ies in intercostal spaces three to six are ligated. Which of the following arteries will be expected to supply these intercostal spaces?","options":["Musculophrenic","Superior epigastric","Posterior intercostal","Lateral thoracic","Thoracodorsa"],"letters":["A","B","C","D","E"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A8","figures":[],"sourceExplanation":"The anterior intercostal arteries anastomose with the posterior intercostal arteries. Ligation of the anterior arteries would not affect the supply of the intercostal spaces because the posterior arteries would provide collateral arterial supply. Branches of the musculophrenic artery provide supply for the lower seventh, eighth, and ninth intercostal spaces. The superior epigastric artery passes into the rectus sheath of the anterior abdominal wall. The lateral thoracic artery arises from the second part of the axillary artery, and the thoracodorsal artery is a branch of the subscapular artery, a branch of the third part of the axillary artery"},{"id":"cvp-working-A9-1","source":"cvp-working-2026","page":15,"endPage":16,"number":"A9-1","question":"When does foramen ovale close after birth?","options":["1–2 years","3–4 weeks","5–6 days","Immediately"],"letters":["A","B","C","D"],"printedAnswer":"D","answer":3,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A9","figures":[],"sourceExplanation":"Functional closure occurs shortly after birth when the ﬁrst breaths lower pulmonary vascular resistance, increasing pulmonary blood ﬂow and left atrial pressure. The higher left atrial pressure presses the septum primum against the septum secundum, closing the foramen ovale."},{"id":"cvp-working-A9-2","source":"cvp-working-2026","page":16,"endPage":16,"number":"A9-2","question":"A newborn baby is known to have multiple cardiac anomalies. An echocardiogram shows a ventricular septal defect, hypertrophy of the right ventricle, pulmonary stenosis and an overriding aorta. Which of the following embryologic defects underlies this condition?","options":["tetralogy of Fallot","Patent ductus arteriosus","Interatrial septal defect","Mitral stenosis"],"letters":["A","B","C","D"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A9","figures":[],"sourceExplanation":"Tetralogy of Fallot results from anterosuperior displacement of the infundibular (conal) septum, causing four features: pulmonary stenosis, ventricular septal defect (VSD), overriding aorta, and right ventricular hypertrophy. Pulmonary stenosis reduces blood ﬂow to the lungs, while the VSD allows mixing of oxygenated and deoxygenated blood, leading to cyanosis."},{"id":"cvp-working-A9-3","source":"cvp-working-2026","page":17,"endPage":17,"number":"A9-3","question":"A newborn presents with cyanosis due to mixing of oxygenated and deoxygenated blood. During embryonic development, which structure normally prevents this mixing by separating the aorta and pulmonary trunk?","options":["Septum primum","Aorticopulmonary septum","Interatrial septum","Interventricular septum"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A9","figures":[],"sourceExplanation":"The aorticopulmonary septum divides the truncus arteriosus into the aorta and pulmonary trunk. Its spiral arrangement allows separation of oxygenated and deoxygenated blood in the systemic and pulmonary circulations."},{"id":"cvp-working-A10-1","source":"cvp-working-2026","page":18,"endPage":18,"number":"A10-1","question":"A section of the myocardium obtained at autopsy is stained with H&E and examined in the pathology department.Identify the structure indicated by the arrow.","options":["arteriole","capillary","lymphatic vessel","small artery","venule"],"letters":["A","B","C","D","E"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A10","figures":[{"page":18,"image":"/working-document-figures/p18-0.webp"}],"sourceExplanation":"Capillaries are the smallest blood vessels. They are composed of a single layer of endothelial cells (a simple squamous epithelium) surrounded by a delicate basal lamina. These narrow endothelial channels are just large enough to allow erythrocytes to pass through, one at a time, and thin enough to allow for efﬁcient transendothelial diffusion ."},{"id":"cvp-working-A10-2","source":"cvp-working-2026","page":19,"endPage":19,"number":"A10-2","question":"A 45-year-old patient develops inﬂammation in the skin. Histological examination reveals a small blood vessel with a thin endothelial lining, discontinuous pericyte coverage, and a surrounding basement membrane. Leukocytes are observed migrating through its wall. Which of the following vessels is most likely involved?","options":["Continuous capillary","Fenestrated capillary","Muscular venule","Postcapillary venule","Sinusoidal capillary"],"letters":["A","B","C","D","E"],"printedAnswer":"D","answer":3,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A10","figures":[],"sourceExplanation":"Postcapillary venules are the primary sites of leukocyte extravasation (diapedesis) during inﬂammation. Their thin endothelial walls and relatively loose junctions facilitate leukocyte migration into surrounding tissues."},{"id":"cvp-working-A10-3","source":"cvp-working-2026","page":19,"endPage":19,"number":"A10-3","question":"Which Organ of the following has Continuous Capillaries?","options":["Spleen","Lungs","Kidney","Liver"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A10","figures":[],"sourceExplanation":""},{"id":"cvp-working-A11-1","source":"cvp-working-2026","page":20,"endPage":20,"number":"A11-1","question":"During cardiac catheterization of a 6-year-old child, the radiologist notes that the contrast medium released into the arch of the aorta is visible immediately in the left pulmonary artery. What is the most likely explanation for this ﬁnding?","options":["Atrial septal defect","Mitral stenosis","Patent ductus arteriosus","Patent ductus venosus","Ventricular septal defect"],"letters":["A","B","C","D","E"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A11","figures":[],"sourceExplanation":"The ductus arteriosus is an embryologic structure that acts as a communication between the pulmonary trunk and the aorta. If it remains patent, the injected contrast medium would ﬂow from the aorta through this communication and into the pulmonary artery. An atrial septal defect is a communication between the atria. Mitral stenosis is a narrowing of the AV valve between the left atrium and left ventricle. The ductus venosus transports blood from the left umbilical vein into the inferior vena cava, bypassing the liver. A ventricular septal defect is a communication between the ventricles."},{"id":"cvp-working-A11-2","source":"cvp-working-2026","page":20,"endPage":20,"number":"A11-2","question":"A man developed a tumor in his posterior mediastinum. Which of the following is probably compressed?","options":["Vagus nerve","Arch of aorta","Arch of azygos","Trachea","Phrenic nerve"],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A11","figures":[],"sourceExplanation":"The vagus nerve passes through the posterior mediastinum and may be compressed by a tumor in this region. The arch of the aorta, arch of the azygos vein, trachea, and phrenic nerve are primarily located in other mediastinal compartments."},{"id":"cvp-working-A11-3","source":"cvp-working-2026","page":21,"endPage":21,"number":"A11-3","question":"A 58-year-old man presents with progressive hoarseness, difﬁculty swallowing, and intermittent shortness of breath. His medical history is signiﬁcant for long-standing hypertension. A CT scan of the chest reveals a large aneurysm involving the arch of the aorta, with compression of several adjacent mediastinal structures. Laryngoscopic examination reveals paralysis of the left vocal cord.Which of the following BEST explains the anatomical mechanism responsible for the patient's vocal cord paralysis?","options":["Compression of the left phrenic nerve as it passes anterior to the root of the lung","Compression of the left recurrent laryngeal nerve as it loops around the aortic arch near the ligamentum arteriosum","Compression of the left vagus nerve as it forms the esophageal plexus in the posterior mediastinum","Compression of the right recurrent laryngeal nerve as it loops around the right subclavian artery","Compression of the sympathetic trunk as it descends through the posterior mediastinum"],"letters":["A","B","C","D","E"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A11","figures":[],"sourceExplanation":"The left recurrent laryngeal nerve branches from the left vagus nerve and loops beneath the aortic arch near the ligamentum arteriosum before ascending towards the larynx. An aneurysm of the aortic arch can compress this nerve, impairing motor innervation to the intrinsic laryngeal muscles (except the cricothyroid), resulting in ipsilateral vocal cord paralysis and hoarseness. The associated dysphagia and dyspnea may result from compression of the esophagus and trachea, respectively."},{"id":"cvp-working-A12-1","source":"cvp-working-2026","page":22,"endPage":22,"number":"A12-1","question":"Following neck surgery, a patient has difﬁculty producing high-pitched sounds due to injury to the external branch of the superior laryngeal nerve. Which muscle is most likely affected?","options":["Posterior cricoarytenoid","Cricothyroid","Lateral cricoarytenoid","Thyroarytenoid"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A12","figures":[],"sourceExplanation":"The cricothyroid muscle stretches and tightens the vocal folds so we can produce sounds at a higher pitch. It receives its nerve supply from the external branch of the superior laryngeal nerve, which explains why damage to this nerve makes those sounds harder to produce. The other muscles listed are supplied by the recurrent laryngeal nerve. You can also ﬁnd this difference in nerve supply on slide 25 of the lecture."},{"id":"cvp-working-A12-2","source":"cvp-working-2026","page":22,"endPage":22,"number":"A12-2","question":"A patient has a blockage of a sinus opening in the superior nasal meatus. Drainage from which paranasal sinus is most likely affected?","options":["Sphenoidal","Maxillary","Anterior ethmoidal","Posterior ethmoidal"],"letters":["A","B","C","D"],"printedAnswer":"D","answer":3,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A12","figures":[],"sourceExplanation":"The posterior ethmoidal sinuses drain into the superior meatus, so a blockage here would prevent them from draining properly. The anterior ethmoidal, frontal, and maxillary sinuses drain into the middle meatus, while the sphenoidal sinus drains into the sphenoethmoidal recess. You can ﬁnd the drainage of the posterior ethmoidal sinuses on slide 8 of the lecture."},{"id":"cvp-working-A12-3","source":"cvp-working-2026","page":23,"endPage":23,"number":"A12-3","question":"A 45-year-old woman develops difﬁculty breathing after thyroid surgery. Laryngoscopy shows that both vocal folds fail to move apart during inspiration. Loss of function of which muscle most directly explains this ﬁnding?","options":["Cricothyroid","Lateral cricoarytenoid","Posterior cricoarytenoid","Transverse arytenoid"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A12","figures":[],"sourceExplanation":"The posterior cricoarytenoid is the only muscle that moves the vocal folds apart, opening the airway during inspiration. Damage to the recurrent laryngeal nerves during thyroid surgery can paralyze these muscles on both sides, leaving the airway narrow and making breathing difﬁcult. Slide 20 identiﬁes this muscle as an abductor, and slide 25 covers its nerve supply."},{"id":"cvp-working-A13-1","source":"cvp-working-2026","page":23,"endPage":23,"number":"A13-1","question":"Which of the following cells in the olfactory epithelium of the nasal cavity is responsible for the regeneration of olfactory perception, in a patient who lost his sense of smell.","options":["Basal cells","Brush cells","Goblet cells","Olfactory neurons","Supporting cells"],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A13","figures":[],"sourceExplanation":"Basal cells act as stem cells that regenerate olfactory receptor neurons, helping restore the sense of smell."},{"id":"cvp-working-A13-2","source":"cvp-working-2026","page":23,"endPage":24,"number":"A13-2","question":"The trachea possesses which one of the following components?","options":["Irregular cartilage plates in its wall","Skeletal muscle in its wall","An epithelium containing only two cell types","A thick basement membrane underlying its epithelium","Bowman glands in its lamina propria"],"letters":["A","B","C","D","E"],"printedAnswer":"D","answer":3,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A13","figures":[],"sourceExplanation":"The pseudostratiﬁed ciliated columnar epithelium lining the trachea rests on a thick basement membrane and contains ﬁve cell types."},{"id":"cvp-working-A13-3","source":"cvp-working-2026","page":24,"endPage":24,"number":"A13-3","question":"Pseudostratiﬁed ciliated columnar epithelium is found in all of the following respiratory organs EXCEPT:","options":["Respiratory region of the nasal cavity","Trachea","Main bronchi","Alveoli","Most of the laryngeal cavity, excluding the true vocal folds"],"letters":["A","B","C","D","E"],"printedAnswer":"D","answer":3,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-A13","figures":[],"sourceExplanation":"Pseudostratiﬁed ciliated columnar epithelium lines most of the conducting respiratory tract, whereas alveoli are lined mainly by simple squamous epithelium to facilitate gas exchange."},{"id":"cvp-working-P1-1","source":"cvp-working-2026","page":33,"endPage":33,"number":"P1-1","question":"Which of the following channels is present in Nodal cells, ventricular myocytes and Purkinje ﬁbers?","options":["Inward rectiﬁer potassium channels","Delayed rectiﬁer potassium channels","T-type calcium channels","Transient outward potassium ( ) channels 𝐼 𝑡𝑜"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P1","figures":[],"sourceExplanation":"Delayed rectiﬁer channels are responsible for phase 3 (repolarization), which occurs in Nodal cells, ventricular cells, and Purkinje cells. Inward rectiﬁers are responsible for maintaining the resting membrane potential in ventricular cells only. T-type channels are only present in nodal cells. Ito channels are responsible for the early repolarization (phase 1), which isn’t present in Nodal cells."},{"id":"cvp-working-P1-2","source":"cvp-working-2026","page":33,"endPage":34,"number":"P1-2","question":"What is the approximate threshold membrane potential at which the S-A node ﬁres an action potential?","options":["-40 mV","-55 mV","-65 mV","-85 mV","-105 mV"],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P1","figures":[],"sourceExplanation":"The normal resting membrane potential of the S-A node is −55 millivolts. As sodium leaks into the membrane, an upward drift of the membrane potential occurs until it reaches −40 millivolts. This is the threshold level that initiates the action potential at the S-A node."},{"id":"cvp-working-P1-3","source":"cvp-working-2026","page":34,"endPage":34,"number":"P1-3","question":"A patient receives a drug that increases potassium conductance in SA nodal cells during phase 4 and decreases the funny current. Assume the drug does not directly affect calcium channels. Which of the following is the most likely effect?","options":["Increased slope of phase 4, shorter time to reach threshold, and increased heart rate","Decreased slope of phase 4, longer time to reach threshold, and decreased heart rate","Reduced phase 1 repolarization in ventricular cells and increased heart rate","Increased slope of phase 0 in SA nodal cells and faster AV conduction","Prolonged ventricular phase 2 due to increased calcium inﬂux"],"letters":["A","B","C","D","E"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P1","figures":[],"sourceExplanation":"C and E are wrong because the question is about nodal cells, not ventricular cells. Increased K ⁺ conductance means more positive charge tends to leave the cell, hyperpolarizing the cell. Decreased funny current means less inward pacemaker current. Phase 4 becomes less steep, so the cell takes longer to reach the threshold. The SA node ﬁres less frequently, so heart rate decreases."},{"id":"cvp-working-P2-1","source":"cvp-working-2026","page":35,"endPage":35,"number":"P2-1","question":"Which of the following mechanisms is responsible for lowering calcium levels in the cytoplasm right before muscle relaxation?","options":["Ryanodine receptor type 2 (RyR2)","L-type calcium channel","Voltage-gated calcium channels","Sodium-calcium exchanger"],"letters":["A","B","C","D"],"printedAnswer":"D","answer":3,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P2","figures":[],"sourceExplanation":"To allow the muscle to relax, calcium must be removed from the cytoplasm. The sodium-calcium exchanger (NCX) pumps calcium out of the cell, which drops the intracellular calcium level. RyR2 releases calcium from storage inside the cell to trigger a contraction. L-type and voltage-gated calcium channels bring calcium into the cell to help start a contraction."},{"id":"cvp-working-P2-2","source":"cvp-working-2026","page":35,"endPage":35,"number":"P2-2","question":"During which phase of the ventricular action potential is the conductance to Ca2+ highest?","options":["Phase 0","Phase 1","Phase 2","Phase 3","Phase 4"],"letters":["A","B","C","D","E"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P2","figures":[],"sourceExplanation":"Phase 2 is the plateau of the ventricular action potential. During this phase, the conductance to Ca2+ increases transiently. Ca2+ that enters the cell during the plateau is the trigger that releases more Ca2+ from the sarcoplasmic reticulum (SR) for contraction."},{"id":"cvp-working-P2-3","source":"cvp-working-2026","page":36,"endPage":36,"number":"P2-3","question":"Which structural components located within the intercalated disks of cardiac muscle cells are critical for the heart's ability to be electrically coupled?","options":["Desmosomes","Gap Junctions","Titin ﬁlaments","T-tubules"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P2","figures":[],"sourceExplanation":"Gap junctions allow action potentials to pass directly and rapidly from one cell to the next. Desmosomes act as structural spot-welds that physically hold adjacent cardiac cells together so they do not pull apart during contraction. Titin and T-tubules are not components of intercalated disks."},{"id":"cvp-working-P3-1","source":"cvp-working-2026","page":36,"endPage":36,"number":"P3-1","question":"When recording lead aVL on an ECG, which is the positive electrode?","options":["Left arm","Left leg","Right leg","Left arm + left leg","Right arm + left leg"],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P3","figures":[],"sourceExplanation":"By convention, the left arm (LA) is the positive electrode for lead aVL."},{"id":"cvp-working-P3-2","source":"cvp-working-2026","page":37,"endPage":37,"number":"P3-2","question":"If Lead III = 0.4 mV and Lead II = 0.9 mV, what is Lead I ?","options":["0.5 mV","1.3 mV","0.12 mV","0.05 mV"],"letters":["A","B","C","D"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P3","figures":[],"sourceExplanation":"Lead I = Lead II − Lead III = 0.9 − 0.4 = 0.5 mV"},{"id":"cvp-working-P3-3","source":"cvp-working-2026","page":37,"endPage":37,"number":"P3-3","question":"What determines the direction and length of a cardiac electrical vector?","options":["Direction points toward depolarized areas; length is proportional to resistance","Direction points toward repolarized (+) areas; length is proportional to voltage","Direction points toward polarized areas; length is proportional to current","Direction points away from repolarized areas; length is proportional to voltage"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P3","figures":[],"sourceExplanation":""},{"id":"cvp-working-P4-1","source":"cvp-working-2026","page":38,"endPage":38,"number":"P4-1","question":"From the ECG shown, which is the most likely condition in this patient?","options":["2nd degree type 1","2nd degree type 2","3rd-degree heart block","Sinus bradycardia"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P4","figures":[{"page":38,"image":"/working-document-figures/p38-0.webp"}],"sourceExplanation":"The P waves are occurring regularly but independently of the QRS complexes, meaning the atria and ventricles are beating at their own separate rates. There is no consistent relationship between the P waves and QRS complexes"},{"id":"cvp-working-P4-2","source":"cvp-working-2026","page":38,"endPage":39,"number":"P4-2","question":"A 50-year-old man has a blood pressure of 140/85 mm Hg and weighs 90.7 kg (200 lb). He reports that he is not feeling well, his ECG has no P waves, he has a heart rate of 46 beats/min, and the QRS complexes occur regularly. What is his likely condition?","options":["Sinus bradycardia","First-degree heart block","Second-degree heart block","Sinoatrial heart block"],"letters":["A","B","C","D"],"printedAnswer":"D","answer":3,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P4","figures":[{"page":38,"image":"/working-document-figures/p38-1.webp"}],"sourceExplanation":"When a patient has no P waves and a low heart rate, it is likely that the impulse leaving the sinus node is totally blocked before entering the atrial muscle, which is called sinoatrial block"},{"id":"cvp-working-P4-3","source":"cvp-working-2026","page":39,"endPage":39,"number":"P4-3","question":"A 70-year-old woman had an ECG at her annual checkup, Used this below chart to calculate her heart rate . Clue there are 4 large squares","options":["60","75","80","100"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P4","figures":[{"page":39,"image":"/working-document-figures/p39-0.webp"}],"sourceExplanation":"To ﬁnd the heart rate from an ECG, divide the 300 by the number of large squares between R-R intervals. Since the R-R interval spans 4 large squares according to the chart's clue, dividing 300 by 4 results in a heart rate of 75 beats per minute."},{"id":"cvp-working-P5-1","source":"cvp-working-2026","page":40,"endPage":40,"number":"P5-1","question":"Which of the following changes is most likely to increase the risk of ventricular ﬁbrillation?","options":["Increased blood potassium concentration","Increased cardiac output","Complete repolarization of cardiac muscle","Increased normal conduction velocity","Prolongation of the cardiac refractory period"],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P5","figures":[],"sourceExplanation":"Increased blood K ⁺ can decrease conduction through cardiac muscle, which favors re-entry (“circus movements”) and can lead to ventricular ﬁbrillation."},{"id":"cvp-working-P5-2","source":"cvp-working-2026","page":40,"endPage":40,"number":"P5-2","question":"A 61-year-old man with a history of myocardial infarction experiences shortness of breath and fatigue. His ECG shows widened QRS complexes in all leads. Which change in cardiac conduction most likely explains this ﬁnding?","options":["Decreased parasympathetic innervation to the heart","Decreased conduction rate along the bundle branches","Decreased conduction rate from the SA node to the AV node","Sinus bradycardia","Sinus tachycardia"],"letters":["A","B","C","D","E"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P5","figures":[],"sourceExplanation":"Slowed conduction through the bundle branches delays ventricular depolarization, widening the QRS complex."},{"id":"cvp-working-P5-3","source":"cvp-working-2026","page":41,"endPage":41,"number":"P5-3","question":"A patient suddenly becomes unable to maintain effective cardiac pumping due to an electrical disturbance. The underlying cardiac condition is described as an inability of the heart to pump rather than a speciﬁc abnormal rhythm. Which of the following best describes the patient’s condition?","options":["Ventricular ﬁbrillation","Atrial ﬁbrillation","Cardiac arrest","Atrial ﬂutter","Myocardial infarction"],"letters":["A","B","C","D","E"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P5","figures":[],"sourceExplanation":"Cardiac arrest is the inability of the heart to pump effectively due to an electrical problem, while ventricular ﬁbrillation is a speciﬁc arrhythmia that can cause cardiac arrest."},{"id":"cvp-working-P6-1","source":"cvp-working-2026","page":41,"endPage":41,"number":"P6-1","question":"What is mostly correlated after the QRS complex on an ECG?","options":["Rapid Ventricular Filling","Slow Ventricular Filling","Isovolumetric Contraction","Isovolumetric Relaxation"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P6","figures":[],"sourceExplanation":"Immediately after the QRS complex, the ventricles begin contracting, causing pressure to rise while all valves remain closed and ventricular volume stays constant"},{"id":"cvp-working-P6-2","source":"cvp-working-2026","page":41,"endPage":42,"number":"P6-2","question":"The following diagram shows the changes in left ventricular pressure (red line) and aortic pressure (blue line) during one heartbeat in a person with aortic valve stenosis. At which point does the aortic valve open?","options":["A","B","C","D","E"],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P6","figures":[{"page":41,"image":"/working-document-figures/p41-0.webp"}],"sourceExplanation":"The aortic valve opens when left ventricular pressure exceeds aortic pressure, allowing blood to ﬂow from the left ventricle into the aorta."},{"id":"cvp-working-P6-3","source":"cvp-working-2026","page":42,"endPage":42,"number":"P6-3","question":"During the cardiac cycle, what speciﬁcally occurs during the last third of diastole?","options":["Rapid inﬂow and ﬁlling of the ventricles","Blood directly ﬂowing from the veins into the ventricle","Contraction of the atria, accounting for 20% of ventricular ﬁlling","Isovolumic relaxation of the ventricles"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P6","figures":[],"sourceExplanation":"The last third of diastole is marked by atrial systole, where the atria contract to pump the remaining blood into the ventricles"},{"id":"cvp-working-P7-1","source":"cvp-working-2026","page":43,"endPage":43,"number":"P7-1","question":"A 60-year-old woman has a resting cardiac output of 5,000 mL/min. Based on the left ventricular pressure-volume loop shown below, calculate her resting heart rate.","options":["40 beats/min","50 beats/min","70 beats/min","100 beats/min"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P7","figures":[{"page":43,"image":"/working-document-figures/p43-0.webp"}],"sourceExplanation":"To calculate the heart rate, we ﬁrst need to ﬁnd the stroke volume using the pressure volume loop. We can see that the end diastolic volume (EDV) is 150 mL, which is the amount of blood in the ventricle before contraction, while the end systolic volume (ESV) is 50 mL, which is the amount of blood left after contraction. By subtracting the ESV from the EDV, we get a stroke volume of 100 mL. Now that we have the stroke volume and the cardiac output of 5,000 mL/min, we simply divide the cardiac output by the stroke volume to get a heart rate of 50 beats/min."},{"id":"cvp-working-P7-2","source":"cvp-working-2026","page":44,"endPage":44,"number":"P7-2","question":"Which of the following correctly describes the pressure relationships during left ventricular isovolumetric contraction?","options":["Aortic pressure is lower than ventricular pressure, while ventricular pressure is higher than atrial pressure","Aortic pressure is higher than ventricular pressure, while ventricular pressure is higher than atrial pressure.","Aortic pressure is higher than ventricular pressure, while ventricular pressure is lower than atrial pressure","Aortic pressure is lower than ventricular pressure, while ventricular pressure is lower than atrial pressure"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P7","figures":[],"sourceExplanation":"During isovolumetric contraction, the left ventricular pressure increases above the left atrial pressure, causing the mitral valve to close. The aortic pressure is still higher than the ventricular pressure, so the aortic valve remains closed. Therefore, the aortic pressure is the highest, followed by the left ventricular pressure, then the left atrial pressure."},{"id":"cvp-working-P7-3","source":"cvp-working-2026","page":44,"endPage":44,"number":"P7-3","question":"A patient experiences an increase in ventricular contractility while preload and afterload remain constant. Which of the following changes would most likely occur in the left ventricular pressure-volume loop?","options":["Increased end systolic volume and decreased stroke volume","Increased end diastolic volume and decreased ejection fraction","Decreased end systolic volume and increased stroke volume","Decreased end diastolic volume and increased afterload"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P7","figures":[],"sourceExplanation":"When contractility increases, the heart contracts with more force, allowing it to pump out more blood. This means less blood is left in the ventricle after contraction, so the end systolic volume (ESV) decreases. Since more blood is being pumped out, both the stroke volume and ejection fraction increase, while preload and afterload stay the same."},{"id":"cvp-working-P8-1","source":"cvp-working-2026","page":45,"endPage":45,"number":"P8-1","question":"Considered as a whole, the body’s capillaries have:","options":["Smaller cross-sectional area than the arteries","Less total blood ﬂow than in the veins","Greater total resistance than the arterioles","Slower blood velocity than in the arteries","Greater total blood ﬂow than in the arteries."],"letters":["A","B","C","D","E"],"printedAnswer":"D","answer":3,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P8","figures":[],"sourceExplanation":"Capillaries have the largest total cross-sectional area, resulting in the slowest blood velocity, which allows sufﬁcient time for material exchange"},{"id":"cvp-working-P8-2","source":"cvp-working-2026","page":45,"endPage":45,"number":"P8-2","question":"If the lumen of one blood vessel decreases from 9 mm to 3 mm, what is the change of resistance?","options":["Decreased by 9x","Increased by 9x","Increased by 81x","Decreased by 81x"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P8","figures":[],"sourceExplanation":"According to Poiseuille’s law, resistance is inversely proportional to the fourth power of the radius (R ∝ 1/r⁴). When the radius decreases from 9 mm to 3 mm, resistance increases by (9/3)⁴ = 3⁴ = 81x fold."},{"id":"cvp-working-P8-3","source":"cvp-working-2026","page":45,"endPage":46,"number":"P8-3","question":"Which part of the circulatory system functions as the main control site for blood ﬂow to different tissues?","options":["Arteries","Arterioles","Capillaries","Veins"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P8","figures":[],"sourceExplanation":"Arterioles act as the main control sites for blood ﬂow because their smooth muscle can constrict or dilate, changing vascular resistance and regulating blood ﬂow to tissues."},{"id":"cvp-working-P9-1","source":"cvp-working-2026","page":46,"endPage":46,"number":"P9-1","question":"Venous compliance:","options":["Decreases with sympathetic stimulation","Increases with sympathetic stimulation","Decreases with parasympathetic stimulation","Increases with parasympathetic stimulation","Not affected by autonomic nerves"],"letters":["A","B","C","D","E"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P9","figures":[],"sourceExplanation":"Decreased sympathetic stimulation causes the smooth muscle in the veins to relax. This relaxation lets the veins expand more easily, thereby increasing venous compliance."},{"id":"cvp-working-P9-2","source":"cvp-working-2026","page":46,"endPage":46,"number":"P9-2","question":"In a skeletal muscle capillary, the capillary hydrostatic pressure (Pc) is 32 mmHg, the capillary oncotic pressure (π c) is 27 mmHg, and the interstitial hydrostatic pressure (Pi) is 2 mmHg. Interstitial oncotic pressure (π i) is negligible. What is the driving force across the capillary wall, and will it favor ﬁltration or absorption?","options":["3 mmHg, favoring absorption","3 mmHg, favoring ﬁltration","7 mmHg, favoring absorption","7 mmHg, favoring ﬁltration","9 mmHg, favoring ﬁltration"],"letters":["A","B","C","D","E"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P9","figures":[],"sourceExplanation":"The driving force is calculated from theStarling forces across the capillary wall. The net pressure = (Pc − Pi) − (π c − π i). Therefore, net pressure = (32 mm Hg − 2 mm Hg) − (27 mm Hg) = +3 mm Hg. Because the sign of the net pressure is positive, ﬁltration is favored."},{"id":"cvp-working-P9-3","source":"cvp-working-2026","page":47,"endPage":47,"number":"P9-3","question":"What would be the pressure in the aorta under conditions of aortic regurgitation?","options":["Low diastolic, low systolic pressure","High Diastolic, low systolic pressure","Low diastolic, high systolic pressure","High diastolic, high systolic pressure"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P9","figures":[],"sourceExplanation":"During diastole, blood leaks backward from the aorta through the incompetent aortic valve into the left ventricle, causing a drop in diastolic pressure. The left ventricle experiences volume overload and pumps a larger stroke volume into the aorta during systole, which elevates the systolic pressure."},{"id":"cvp-working-P10-1","source":"cvp-working-2026","page":47,"endPage":47,"number":"P10-1","question":"A person has a left ventricular systolic pressure of 180 mmHg and an aortic systolic pressure of 110 mmHg. What is the explanation?","options":["Mitral stenosis","Aortic regurgitation","Aortic stenosis","Mitral regurgitation"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P10","figures":[],"sourceExplanation":"The narrowed aortic valve obstructs blood ﬂow during ventricular ejection, creating a large systolic pressure difference between the left ventricle and aorta."},{"id":"cvp-working-P10-2","source":"cvp-working-2026","page":48,"endPage":48,"number":"P10-2","question":"A patient undergoing cardiac assessment has a diastolic murmur, an enlarged left atrium, and left ventricular end-diastolic volume of 70 mL. Which valvular lesion best explains these ﬁndings?","options":["Aortic regurgitation","Pulmonary regurgitation","Mitral stenosis","Aortic stenosis","Pulmonary stenosis"],"letters":["A","B","C","D","E"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P10","figures":[],"sourceExplanation":"The narrowed mitral valve restricts ventricular ﬁlling during diastole. Blood backs up into the left atrium, increasing its pressure and causing enlargement."},{"id":"cvp-working-P10-3","source":"cvp-working-2026","page":48,"endPage":48,"number":"P10-3","question":"An infant has a continuous “machinery” murmur caused by a patent ductus arteriosus. After pulmonary vascular resistance has fallen following birth, which direction does blood normally ﬂow through this abnormal connection?","options":["Pulmonary artery → aorta","Left atrium → right atrium","Aorta → pulmonary artery","Right ventricle → left ventricle"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P10","figures":[],"sourceExplanation":"Aortic pressure exceeds pulmonary artery pressure, producing a left to right shunt and increasing blood ﬂow through the lungs."},{"id":"cvp-working-P11-1","source":"cvp-working-2026","page":49,"endPage":49,"number":"P11-1","question":"A patient at rest is given a drug that reduces the venous compliance but has no other cardiac or vascular effects. What effect will this drug have on venous return and venous blood capacity?","options":["Venous return decreases and venous capacity increases","Venous return decreases and venous capacity will not change","Venous return increases and venous capacity decreases","Venous return decreases and venous capacity will not change"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P11","figures":[],"sourceExplanation":"When the veins become stiffer, they can’t stretch to hold as much blood, so their capacity goes down. The amount of blood in the body is still the same, so the extra blood gets pushed out of the veins and the pressure inside the circulation goes up. This higher pressure (mean systemic ﬁlling pressure) pushes blood back to the heart harder, so venous return increases."},{"id":"cvp-working-P11-2","source":"cvp-working-2026","page":49,"endPage":49,"number":"P11-2","question":"Under conditions of constant arterial pressure, what is the effect of arteriolar vasodilation on the blood pressure within the downstream capillaries of a single organ?","options":["Capillary blood pressure decreases to zero","Capillary blood pressure increases","Capillary blood pressure decreases slightly","Capillary blood pressure remains unchanged"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P11","figures":[],"sourceExplanation":"When arterioles dilate, resistance decreases, which reduces the pressure drop across the arterioles and causes capillary hydrostatic blood pressure downstream to rise above the initial state. Conversely, arteriolar vasoconstriction increases the pressure drop and lowers capillary pressure"},{"id":"cvp-working-P11-3","source":"cvp-working-2026","page":50,"endPage":50,"number":"P11-3","question":"A 54-year-old man is admitted to the intensive care unit for hemodynamic monitoring. A catheterization proﬁle reveals a Mean Arterial Pressure (MAP) of 102 mmHg and a Right Atrial Pressure (RAP) of 2 mmHg . His Total Peripheral Resistance (TPR) is calculated to be 20 mmHg/L/min . Based on these measurements, what is this patient's Cardiac Output (CO)?","options":["4.0 L/min","4.5 L/min","5.0 L/min","6.0 L/min"],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P11","figures":[],"sourceExplanation":"by applying this equation ( CO = (MAP - RAP) / TPR ) it will be ( 102 - 2 ) / 20 = 5"},{"id":"cvp-working-P12-1","source":"cvp-working-2026","page":50,"endPage":50,"number":"P12-1","question":"During acute hemorrhage, which of the following changes occurs as a result of the arterial baroreceptor reﬂex?","options":["Decreased sympathetic activity and decreased heart rate","Increased sympathetic activity and increased heart rate","Decreased peripheral vascular resistance","Increased parasympathetic activity and decreased cardiac contractility","Decreased venous return with decreased sympathetic activity"],"letters":["A","B","C","D","E"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P12","figures":[],"sourceExplanation":"Hemorrhage decreases arterial pressure, reducing baroreceptor ﬁring. This increases sympathetic activity and decreases parasympathetic activity, causing increased heart rate, contractility, and peripheral vasoconstriction."},{"id":"cvp-working-P12-2","source":"cvp-working-2026","page":51,"endPage":51,"number":"P12-2","question":"Activation of the baroreceptors will cause:","options":["Stimulation of the cardioaccelerator center in the brain","Increased sympathetic stimulation of the heart","Increased activity by the parasympathetic nervous system","Stimulation of the vasoconstrictive center","Increased heart rate"],"letters":["A","B","C","D","E"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P12","figures":[],"sourceExplanation":"Activation of baroreceptors increases parasympathetic activity and decreases sympathetic activity, leading to a decrease in heart rate and blood pressure."},{"id":"cvp-working-P12-3","source":"cvp-working-2026","page":51,"endPage":52,"number":"P12-3","question":"A 60-year-old man presents with severe hypotension, with a mean arterial pressure of 70 mmHg. His arterial blood gas analysis reveals decreased oxygen levels and increased carbon dioxide levels. Which of the following responses is most likely to occur due to activation of the peripheral chemoreceptors?","options":["Decreased sympathetic activity","Increased parasympathetic activity","Increased sympathetic activity through stimulation of the vasomotor center","Decreased peripheral vascular resistance","Decreased heart rate"],"letters":["A","B","C","D","E"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P12","figures":[],"sourceExplanation":"Low oxygen, increased carbon dioxide, and increased hydrogen ions activate the peripheral chemoreceptors in the carotid and aortic bodies. Their impulses reach the vasomotor center in the brainstem, increasing sympathetic activity. The chemoreceptor reﬂex becomes more signiﬁcant when arterial pressure falls below approximately 80 mmHg."},{"id":"cvp-working-P13-1","source":"cvp-working-2026","page":52,"endPage":52,"number":"P13-1","question":"How can ﬂuid retention help restore stroke volume in heart failure, and how can it lead to edema formation?","options":["By increasing myocardial contractility and decreasing capillary pressure","By increasing ventricular ﬁlling and increasing capillary hydrostatic pressure","By decreasing venous return and increasing plasma oncotic pressure","By decreasing ventricular ﬁlling and increasing lymphatic drainage"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P13","figures":[],"sourceExplanation":"Fluid retention increases blood volume, venous return, and end-diastolic volume, helping restore stroke volume through the Frank–Starling mechanism. However, increased venous pressure raises capillary hydrostatic pressure, promoting ﬂuid movement into the tissues and causing edema."},{"id":"cvp-working-P13-2","source":"cvp-working-2026","page":53,"endPage":53,"number":"P13-2","question":"Following myocardial damage, a patient develops compensated heart failure. Resting cardiac output has returned close to normal. Which ﬁnding is characteristic of this compensated state?","options":["Elevated right atrial pressure","Persistently reduced resting cardiac output","Reduced venous return below normal","Complete restoration of cardiac reserve"],"letters":["A","B","C","D"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P13","figures":[],"sourceExplanation":"Sympathetic activation, renal ﬂuid retention, and partial myocardial recovery can restore resting cardiac output toward normal. However, this compensation occurs at an elevated right atrial pressure, and cardiac reserve remains reduced."},{"id":"cvp-working-P13-3","source":"cvp-working-2026","page":53,"endPage":53,"number":"P13-3","question":"A patient with severe myocardial damage continues to retain sodium and water despite sympathetic activation and increasing blood volume. Which mechanism best explains progression to decompensated heart failure?","options":["The kidneys excrete more ﬂuid than the patient takes in.","Cardiac output rises sufﬁciently to restore normal ﬂuid balance.","The heart cannot maintain sufﬁcient output for the kidneys to excrete the daily ﬂuid load.","Increased atrial natriuretic peptide completely prevents ﬂuid accumulation."],"letters":["A","B","C","D"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P13","figures":[],"sourceExplanation":"In decompensated heart failure, compensatory mechanisms cannot restore sufﬁcient cardiac output to maintain renal ﬂuid balance. Continued sodium and water retention worsens congestion and edema and further increases the workload on the failing heart."},{"id":"cvp-working-P14-1","source":"cvp-working-2026","page":54,"endPage":54,"number":"P14-1","question":"An increase in shear stress in a blood vessel results in which change?","options":["Decreased endothelin production","Decreased cyclic guanosine monophosphate production","Increased nitric oxide release","Increased renin production","Decreased prostacyclin production"],"letters":["A","B","C","D","E"],"printedAnswer":"C","answer":2,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P14","figures":[],"sourceExplanation":"An increase in shear stress in blood vessels is one of the major stimuli for the release of nitric oxide by endothelial cells. Nitric oxide increases blood ﬂow by increasing cyclic guanosine monophosphate."},{"id":"cvp-working-P14-2","source":"cvp-working-2026","page":54,"endPage":54,"number":"P14-2","question":"An aerobically ﬁt 25-year-old woman is exercising in her local gym. From the attached table, which of the following changes in venous compliance, pulse pressure, and total peripheral resistance will most likely occur during normal hemodynamic response to exercise?","options":["Venous Compliance: Increase, Pulse Pressure: Increase, TPR: Increase","Venous Compliance: Increase, Pulse Pressure: Increase, TPR: Decrease","Venous Compliance: Increase, Pulse Pressure: Decrease, TPR: Increase","Venous Compliance: Decrease, Pulse Pressure: Decrease, TPR: Increase","Venous Compliance: Decrease, Pulse Pressure: Increase, TPR: Decrease F. Venous Compliance: Decrease, Pulse Pressure: Decrease, TPR: Decrease"],"letters":["A","B","C","D","E"],"printedAnswer":"E","answer":4,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P14","figures":[],"sourceExplanation":"The veins hold a huge reservoir of blood and therefore during exercise venoconstriction mobilizes blood from the venous reservoir, increasing venous return and supporting stroke volume and in turn works to increase blood volume and distribute more blood around the body. Venoconstriction leads to a decrease in venous compliance. Pulse pressure increases due to an increase in stroke volume. Total peripheral resistance decreases due to the vasodilation of blood vessels leading to increased blood ﬂow."},{"id":"cvp-working-P14-3","source":"cvp-working-2026","page":55,"endPage":55,"number":"P14-3","question":"Which ion will cause vasoconstriction?","options":["Calcium","Potassium","Hydrogen ions","Magnesium"],"letters":["A","B","C","D"],"printedAnswer":"A","answer":0,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P14","figures":[],"sourceExplanation":"An increase in cytosolic calcium ( ) ions inside vascular 𝐶 𝑎 2 + smooth muscle cells directly activates contractile proteins (such as myosin light chain kinase), leading to muscle contraction and vessel narrowing."},{"id":"cvp-working-P15-1","source":"cvp-working-2026","page":55,"endPage":55,"number":"P15-1","question":"At the arterial end of a capillary, you are given: Capillary hydrostatic pressure (Pc) = 30 mmHg Plasma colloid osmotic pressure (îc) = 28 mmHg Interstitial ﬂuid colloid osmotic pressure (rif) = 8 mmHg Interstitial ﬂuid hydrostatic pressure (Pif) = -3 mmHg What is the Net Filtration Pressure (NFP) and the resulting ﬂuid movement?","options":["+10 mmHg, Filtration","+13 mmHg, Filtration","-7 mmHg, Reabsorption","+13 mmHg, Reabsorption"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P15","figures":[],"sourceExplanation":"Formula from lecture: NFP = Pc - π c + π if - Pif. Since Pif is -3, it's - (-3) = +3. So NFP = 30 - 28 + 8 + 3 = 13 mmHg. Positive = outward movement = Filtration. At venous end Pc drops to 10, NFP becomes -7 = Reabsorption. Professor said: \"You must memorize the formula, not the numbers."},{"id":"cvp-working-P15-2","source":"cvp-working-2026","page":56,"endPage":56,"number":"P15-2","question":"Venous Return vs Blood Volume - Shift vs Rotation* A healthy person receives a rapid IV infusion of 1L saline. What happens immediately to the Mean Systemic Filling Pressure (MSFP) and the venous return curve?","options":["MSFP unchanged, venous return curve rotates to the right","MSFP increases from 7 to ∼ 16 mmHg, venous return curve shifts to the right","MSFP decreases, venous return curve shifts to the left","MSFP increases, cardiac output curve shifts to the right"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P15","figures":[],"sourceExplanation":"This was the most emphasized distinction. MSFP is the pressure exerted by blood volume when heart stops = ∼ 7 mmHg normally. Adding volume = more blood in vessels = higher MSFP. Any increase in blood volume causes a *SHIFT* (parallel movement) of the venous return curve to the right. Within 10-40 min, compensatory mechanisms return it: 1- Increased capillary ﬁltration 2- Stress relaxation of veins 3- Increased arteriolar resistance by autoregulation."},{"id":"cvp-working-P15-3","source":"cvp-working-2026","page":56,"endPage":56,"number":"P15-3","question":"A patient on chronic hemodialysis has a large surgical AV ﬁstula created between radial artery and cephalic vein. Immediately after opening the ﬁstula, what happens to cardiac output, venous return, and MSFP?","options":["Cardiac output decreases, MSFP increases, curve shifts right","Cardiac output and venous return increase markedly, MSFP unchanged initially, curve rotates right","Cardiac output unchanged, MSFP decreases, curve shifts left","Cardiac output increases slightly, MSFP decreases due to loss of peripheral resistance Correct"],"letters":["A","B","C","D"],"printedAnswer":"B","answer":1,"type":"mcq","tbl":null,"caseText":"","lectureId":"CVP-P15","figures":[],"sourceExplanation":""}],"set":{"id":"cvp-working-a13-p15","title":"CVP working document · A1–A13 & P1–P15","category":"topic","url":"/working-document-source.html","ids":["cvp-working-A1-1","cvp-working-A1-2","cvp-working-A1-3","cvp-working-A2-1","cvp-working-A2-2","cvp-working-A2-3","cvp-working-A3-1","cvp-working-A3-2","cvp-working-A3-3","cvp-working-A4-1","cvp-working-A4-2","cvp-working-A4-3","cvp-working-A5-1","cvp-working-A5-2","cvp-working-A5-3","cvp-working-A6-1","cvp-working-A6-2","cvp-working-A6-3","cvp-working-A7-1","cvp-working-A7-2","cvp-working-A7-3","cvp-working-A8-1","cvp-working-A8-2","cvp-working-A8-3","cvp-working-A9-1","cvp-working-A9-2","cvp-working-A9-3","cvp-working-A10-1","cvp-working-A10-2","cvp-working-A10-3","cvp-working-A11-1","cvp-working-A11-2","cvp-working-A11-3","cvp-working-A12-1","cvp-working-A12-2","cvp-working-A12-3","cvp-working-A13-1","cvp-working-A13-2","cvp-working-A13-3","cvp-working-P1-1","cvp-working-P1-2","cvp-working-P1-3","cvp-working-P2-1","cvp-working-P2-2","cvp-working-P2-3","cvp-working-P3-1","cvp-working-P3-2","cvp-working-P3-3","cvp-working-P4-1","cvp-working-P4-2","cvp-working-P4-3","cvp-working-P5-1","cvp-working-P5-2","cvp-working-P5-3","cvp-working-P6-1","cvp-working-P6-2","cvp-working-P6-3","cvp-working-P7-1","cvp-working-P7-2","cvp-working-P7-3","cvp-working-P8-1","cvp-working-P8-2","cvp-working-P8-3","cvp-working-P9-1","cvp-working-P9-2","cvp-working-P9-3","cvp-working-P10-1","cvp-working-P10-2","cvp-working-P10-3","cvp-working-P11-1","cvp-working-P11-2","cvp-working-P11-3","cvp-working-P12-1","cvp-working-P12-2","cvp-working-P12-3","cvp-working-P13-1","cvp-working-P13-2","cvp-working-P13-3","cvp-working-P14-1","cvp-working-P14-2","cvp-working-P14-3","cvp-working-P15-1","cvp-working-P15-2","cvp-working-P15-3"],"note":"84 source questions · three per lecture · original option order, supplied keys and explanations. Includes source figures. Source explanation inconsistencies are flagged."}};ORIGINAL_EXAMS.sources.push(data.source);ORIGINAL_EXAMS.questions.push(...data.questions);ORIGINAL_EXAMS.sets.push(data.set);render();})();
